#include <gkyl_gyrokinetic_priv.h>

typedef void (*write_fdot_func_t)(gkyl_gyrokinetic_app *app, struct gkyl_array *fout[]);

static void
write_fdot_enabled(gkyl_gyrokinetic_app *app, struct gkyl_array *fout[])
{
  for (int i = 0; i < app->num_species; ++i) {
    gk_species_write_fdot(app, &app->species[i], fout[i]);
  }
}

static void
write_fdot_disabled(gkyl_gyrokinetic_app *app, struct gkyl_array *fout[])
{
  // Do nothing.
}

static void
gyrokinetic_forward_euler(
  gkyl_gyrokinetic_app *app, double tcurr, double dt, const struct gkyl_array *fin[],
  struct gkyl_array *fout[], const struct gkyl_array *fbar_in[], struct gkyl_array *fbar_out[],
  struct gkyl_array **bflux_in[], struct gkyl_array **bflux_out[],
  const struct gkyl_array *fin_neut[], struct gkyl_array *fout_neut[],
  struct gkyl_array **bflux_in_neut[], struct gkyl_array **bflux_out_neut[],
  write_fdot_func_t write_fdot_func, struct gkyl_update_status *st
)
{
  struct timespec wst_fe = gkyl_wall_clock();
  // Take a forward Euler step with the suggested time-step dt. This may
  // not be the actual time-step taken. However, the function will never
  // take a time-step larger than dt even if it is allowed by
  // stability. The actual time-step and dt_suggested are returned in
  // the status object.
  app->stat.nfeuler += 1;

  // Compute the time rate of change of the distributions, df/dt.
  gyrokinetic_rhs(
    app, tcurr, dt, fin, fbar_in, fout, bflux_out, fin_neut, fout_neut, bflux_out_neut, st
  );

  write_fdot_func(app, fout);

  struct timespec wst = gkyl_wall_clock();
  // Complete update of distribution functions.
  double dta = st->dt_actual;
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gks = &app->species[i];
    gk_species_step_f(gks, fout[i], dta, fin[i]);
    gk_species_damping_forward_euler(app, gks, fin[i], fbar_in[i], fbar_out[i], dta);
    gk_species_bflux_accumulate(app, &gks->bflux, bflux_out[i], 1.0, bflux_in[i]);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    struct gk_neut_species *gkns = &app->neut_species[i];
    gk_neut_species_step_f(gkns, fout_neut[i], dta, fin_neut[i]);
    gk_neut_species_bflux_accumulate(app, &gkns->bflux, bflux_out_neut[i], 1.0, bflux_in_neut[i]);
  }
  app->stat.fwd_euler_step_f_tm += gkyl_time_diff_now_sec(wst);
  app->stat.fwd_euler_tm += gkyl_time_diff_now_sec(wst_fe);
}

